package com.csust.eyediagnosis.workflow.graph.runtime;

import com.csust.eyediagnosis.workflow.contract.*; import com.csust.eyediagnosis.workflow.domain.*; import com.csust.eyediagnosis.workflow.persistence.entity.*; import com.csust.eyediagnosis.workflow.persistence.repository.*;
import org.flywaydb.core.Flyway; import org.junit.jupiter.api.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.jdbc.datasource.*; import org.springframework.transaction.support.TransactionTemplate;
import java.sql.*; import java.time.LocalDateTime; import java.util.*; import static org.junit.jupiter.api.Assertions.*;

/** Real MySQL proof that the accepted Envelope delta is atomic; reservation is intentionally outside this transaction. */
class InferenceEnvelopeDeltaMysqlIT {
    private static final String SCHEMA="eye_diagnosis_inference_it"; private JdbcTemplate jdbc; private Flyway flyway; private TransactionTemplate tx;
    @BeforeEach void setup() throws Exception { String url=System.getenv("WORKFLOW_IT_MYSQL_URL"), user=System.getenv("WORKFLOW_IT_MYSQL_USERNAME"), pass=System.getenv("WORKFLOW_IT_MYSQL_PASSWORD"); Assumptions.assumeTrue(url!=null&&user!=null&&pass!=null); try(Connection c=DriverManager.getConnection(url,user,pass)){assertEquals(SCHEMA,c.getCatalog());} flyway=Flyway.configure().dataSource(url,user,pass).cleanDisabled(false).locations("classpath:db/migration","classpath:db/callback").load(); flyway.clean();flyway.migrate(); DriverManagerDataSource ds=new DriverManagerDataSource(url,user,pass);jdbc=new JdbcTemplate(ds);tx=new TransactionTemplate(new DataSourceTransactionManager(ds)); fixture(); }
    @AfterEach void clean(){if(flyway!=null)flyway.clean();}
    @Test void insertsEnvelopeCompletesReservationAndCasAttachesWorkflowTogether(){tx.executeWithoutResult(s->writer().write(delta()));assertEquals(1L,count("t_inference_envelope"));assertEquals("COMPLETED",text("SELECT status FROM t_workflow_node_execution WHERE nodeExecutionId='node'"));assertNotNull(text("SELECT inferenceEnvelopeId FROM t_diagnosis_workflow WHERE workflowId='wf'"));}
    @Test void exceptionAfterDeltaRollsBackAcceptedStateButNotIndependentReservation(){assertThrows(IllegalStateException.class,()->tx.executeWithoutResult(s->{writer().write(delta());throw new IllegalStateException("rollback");}));assertEquals(0L,count("t_inference_envelope"));assertEquals("INVOKING",text("SELECT status FROM t_workflow_node_execution WHERE nodeExecutionId='node'"));assertNull(text("SELECT inferenceEnvelopeId FROM t_diagnosis_workflow WHERE workflowId='wf'"));}
    private InferenceEnvelopeDeltaWriter writer(){return new InferenceEnvelopeDeltaWriter(new InferenceEnvelopeRepository(){public int insert(InferenceEnvelopeEntity e){return jdbc.update("INSERT INTO t_inference_envelope(inferenceEnvelopeId,workflowId,inferenceEpoch,imageObjectReference,inputDigest,qualityOutcome,qualityScore,inferenceOutcomeType,technicalFailureCode,modelVersion,modelWeightFingerprint,preprocessVersion,inferencePolicyVersion,inferredAt) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)",e.getInferenceEnvelopeId(),e.getWorkflowId(),e.getInferenceEpoch(),e.getImageObjectReference(),e.getInputDigest(),e.getQualityOutcome(),e.getQualityScore(),e.getInferenceOutcomeType(),e.getTechnicalFailureCode(),e.getModelVersion(),e.getModelWeightFingerprint(),e.getPreprocessVersion(),e.getInferencePolicyVersion(),e.getInferredAt());}public Optional<InferenceEnvelopeEntity> findByWorkflowIdAndEpoch(String w,long e){return Optional.empty();}},new NodeExecutionRepository(){public int insertIfAbsent(WorkflowNodeExecutionEntity e){return 0;}public int complete(WorkflowNodeExecutionEntity e){return jdbc.update("UPDATE t_workflow_node_execution SET status=?,outputDigest=?,resultReference=?,completedAt=?,updatedAt=? WHERE nodeExecutionId=?",e.getStatus(),e.getOutputDigest(),e.getResultReference(),e.getCompletedAt(),e.getUpdatedAt(),e.getNodeExecutionId());}public Optional<WorkflowNodeExecutionEntity> findByIdempotencyKey(String k){return Optional.empty();}},new DiagnosisWorkflowRepository(){public Optional<DiagnosisWorkflowEntity> findByWorkflowId(String i){return Optional.empty();}public Optional<DiagnosisWorkflowEntity> findByOwnerAndIdempotencyKey(Long o,String i){return Optional.empty();}public List<ActiveWorkflowGraphBinding> findNonTerminalGraphBindings(){return List.of();}public int insert(DiagnosisWorkflowEntity e){return 0;}public int updateStateIfVersionMatches(String a,long b,String c,String d,String e,String f,String g,String h,String i){return 0;}public int attachInferenceEnvelopeIfVersionMatches(String w,long v,String id){return jdbc.update("UPDATE t_diagnosis_workflow SET inferenceEnvelopeId=? WHERE workflowId=? AND workflowVersion=?",id,w,v);}});}
    private InferenceEnvelopeDelta delta(){InferenceEnvelope e=new InferenceEnvelope("wf",0,"file:/x","digest","image/png",new ImageQualitySnapshot(100,false,Set.of()),InferenceOutcomeType.TECHNICAL_FAILURE,null,null,TechnicalFailureCode.GRPC_TIMEOUT,new OodSnapshot(false,"not-provided",null),new CalibrationSnapshot("not-provided",null),"not-provided","not-provided","not-provided","not-provided","2026-01-01T00:00:00Z");return new InferenceEnvelopeDelta(e,new NodeExecutionCompletion("node","out","pending"),3);}
    private void fixture(){jdbc.update("INSERT INTO t_diagnosis_workflow(workflowId,ownerUserId,creationIdempotencyKey,status,currentSegmentCode,graphDefinitionVersion,graphDefinitionHash,actionVersion,workflowVersion,explanationPublicationStatus,predictionExposureStatus) VALUES('wf',1,'key','RUNNING','INTAKE_INFERENCE_QUALITY','v','h','a',3,'NONE','NOT_AVAILABLE')");jdbc.update("INSERT INTO t_workflow_node_execution(nodeExecutionId,workflowId,executionEpoch,segmentCode,nodeCode,idempotencyKey,status) VALUES('node','wf',0,'INTAKE_INFERENCE_QUALITY','IMAGE_INFERENCE','key','INVOKING')");}
    private long count(String t){return jdbc.queryForObject("SELECT COUNT(*) FROM "+t,Long.class);} private String text(String sql){return jdbc.queryForObject(sql,String.class);}
}
